fit_expected<Weight> dense_weight(const std::vector<Eigen::MatrixXd>& blocks,
                                  FitError::Kind err_kind,
                                  const std::string& detail) {
  Weight out;
  out.reserve(blocks.size());
  for (std::size_t b = 0; b < blocks.size(); ++b) {
    auto bw = BlockWeight::dense(blocks[b], err_kind,
                                 detail + ": block " + std::to_string(b));
    if (!bw.has_value()) return std::unexpected(bw.error());
    out.push_back(std::move(*bw));
  }
  return out;
}

fit_expected<optim::GmmProblem>
residuals(MomentEvaluationFn evaluate, Eigen::Index n_param,
          const data::SampleStats& samp, const Eigen::VectorXd& x0,
          const Weight& weight, optim::ExpandFn expand) {
  auto eval0 = evaluate(x0, false, false);
  if (!eval0.has_value()) {
    return std::unexpected(eval0.error());
  }
  if (auto ok = validate_common_shapes(samp, eval0->moments, "gmm::residuals");
      !ok.has_value()) {
    return std::unexpected(ok.error());
  }
  const Layout layout = make_layout(samp, eval0->moments);

  // Each BlockWeight already carries its own whitening form — Dense factored
  // at construction, Identity/Diagonal/NormalTheory needing no factorization
  // at all — so this only checks shape. Empty ⇒ identity (no whitening).
  if (!weight.empty()) {
    if (weight.size() != samp.S.size()) {
      return std::unexpected(make_err(FitError::Kind::NumericIssue,
          "gmm::residuals: weight block count " +
              std::to_string(weight.size()) +
              " does not match sample block count " +
              std::to_string(samp.S.size())));
    }
    for (std::size_t b = 0; b < weight.size(); ++b) {
      if (!weight[b].valid(layout.block_rows[b])) {
        return std::unexpected(make_err(FitError::Kind::NumericIssue,
            "gmm::residuals: block " + std::to_string(b) +
                " weight dimension does not match moment dimension " +
                std::to_string(layout.block_rows[b])));
      }
    }
  }

  optim::GmmProblem prob;
  prob.n_resid = layout.n_rows;
  prob.n_param = n_param;
  prob.expand  = std::move(expand);
  prob.r = [evaluate, samp, layout, weight](
               const Eigen::VectorXd& x) -> fit_expected<Eigen::VectorXd> {
    auto e = evaluate(x, false, false);
    if (!e.has_value()) {
      return std::unexpected(e.error());
    }
    return weighted_residuals(samp, e->moments, layout, weight);
  };
  prob.J = [evaluate, samp, layout, weight](
               const Eigen::VectorXd& x) -> fit_expected<Eigen::MatrixXd> {
    auto e = evaluate(x, true, layout.has_means);
    if (!e.has_value()) {
      return std::unexpected(e.error());
    }
    return weighted_jacobian(samp, e->moments, e->J_sigma, e->J_mu, layout,
                             weight);
  };
  prob.eval = [evaluate, samp, layout, weight](
                  const Eigen::VectorXd& x) -> fit_expected<optim::LsEvaluation> {
    auto e = evaluate(x, true, layout.has_means);
    if (!e.has_value()) {
      return std::unexpected(e.error());
    }
    auto r = weighted_residuals(samp, e->moments, layout, weight);
    if (!r.has_value()) return std::unexpected(r.error());
    auto J = weighted_jacobian(samp, e->moments, e->J_sigma, e->J_mu, layout,
                               weight);
    if (!J.has_value()) return std::unexpected(J.error());
    return optim::LsEvaluation{std::move(*r), std::move(*J)};
  };
  return prob;
}

fit_expected<optim::GmmProblem>
residuals(const model::ModelEvaluator& ev, const data::SampleStats& samp,
          const Eigen::VectorXd& theta0, const Weight& weight) {
  MomentEvaluationFn evaluate = [&ev](const Eigen::VectorXd& x,
                                      bool with_sigma_jacobian,
                                      bool with_mu_jacobian)
      -> fit_expected<model::Evaluation> {
    auto e = ev.evaluate(x, with_sigma_jacobian, with_mu_jacobian);
    if (!e.has_value()) {
      return std::unexpected(model_err(e.error(), "gmm evaluate"));
    }
    return std::move(*e);
  };
  return residuals(std::move(evaluate),
                   static_cast<Eigen::Index>(ev.n_free()), samp, theta0,
                   weight, [](const Eigen::VectorXd& x) { return x; });
}

fit_expected<Weight>
normal_theory_weight(const model::ModelEvaluator& ev,
                     const data::SampleStats& samp,
                     const Eigen::VectorXd& theta0) {
  auto eval0 = ev.evaluate(theta0, false, false);
  if (!eval0.has_value()) {
    return std::unexpected(
        model_err(eval0.error(), "gmm::normal_theory_weight: theta0"));
  }
  if (auto ok = validate_common_shapes(samp, eval0->moments,
                                       "gmm::normal_theory_weight");
      !ok.has_value()) {
    return std::unexpected(ok.error());
  }
  const Layout layout = make_layout(samp, eval0->moments);

  Weight W;
  W.reserve(samp.S.size());
  for (std::size_t b = 0; b < samp.S.size(); ++b) {
    if (!samp.S[b].allFinite()) {
      return std::unexpected(make_err(FitError::Kind::NumericIssue,
          "gmm::normal_theory_weight: block " + std::to_string(b) +
              " sample covariance contains non-finite entries"));
    }
    // Structured: stores chol(S_b) only. `to_dense()` reproduces the q×q form
    // this used to materialize (pinned in gls_scalar_objective_test.cpp).
    auto bw = BlockWeight::normal_theory(
        samp.S[b], layout.has_means, FitError::Kind::NonPositiveDefiniteSample,
        "gmm::normal_theory_weight: block " + std::to_string(b));
    if (!bw.has_value()) return std::unexpected(bw.error());
    W.push_back(std::move(*bw));
  }
  return W;
}

fit_expected<optim::ScalarProblem>
normal_theory_objective(const model::ModelEvaluator& ev,
                        const data::SampleStats& samp,
                        const Eigen::VectorXd& theta0) {
  auto eval0 = ev.evaluate(theta0, false, false);
  if (!eval0.has_value()) {
    return std::unexpected(
        model_err(eval0.error(), "gmm::normal_theory_objective: theta0"));
  }
  if (auto ok = validate_common_shapes(samp, eval0->moments,
                                       "gmm::normal_theory_objective");
      !ok.has_value()) {
    return std::unexpected(ok.error());
  }
  auto N = total_n_obs(samp);
  if (!N.has_value()) return std::unexpected(N.error());

  NtScalarCache cache;
  cache.layout = make_layout(samp, eval0->moments);
  cache.S_inv.resize(samp.S.size());
  cache.w_block.resize(samp.S.size());
  for (std::size_t b = 0; b < samp.S.size(); ++b) {
    const Eigen::Index p = samp.S[b].rows();
    Eigen::LLT<Eigen::MatrixXd> llt(samp.S[b]);
    if (llt.info() != Eigen::Success) {
      return std::unexpected(make_err(FitError::Kind::NonPositiveDefiniteSample,
          "gmm::normal_theory_objective: block " + std::to_string(b) +
              " sample covariance is not positive definite"));
    }
    cache.S_inv[b] = llt.solve(Eigen::MatrixXd::Identity(p, p));
    cache.w_block[b] = static_cast<double>(samp.n_obs[b]) /
                       static_cast<double>(*N);
  }

  optim::ScalarProblem prob;
  prob.n_param = static_cast<Eigen::Index>(ev.n_free());
  prob.expand  = [](const Eigen::VectorXd& x) { return x; };
  prob.f = [&ev, s = samp, c = std::move(cache)](
               const Eigen::VectorXd& x, Eigen::VectorXd& grad) -> double {
    auto eval = ev.evaluate(x, true, true);
    if (!eval.has_value()) {
      grad.setZero();
      return kInfinity;
    }
    const auto&   m = eval->moments;
    const Layout& L = c.layout;

    Eigen::VectorXd wv = Eigen::VectorXd::Zero(L.n_sigma_rows);
    Eigen::VectorXd uv = Eigen::VectorXd::Zero(L.n_mu_rows);
    double f = 0.0;

    for (std::size_t b = 0; b < m.sigma.size(); ++b) {
      const Eigen::Index      p  = m.sigma[b].rows();
      const Eigen::MatrixXd&  Si = c.S_inv[b];
      const double            wb = c.w_block[b];

      const Eigen::MatrixXd D = m.sigma[b] - s.S[b];
      Eigen::MatrixXd G = Si * D * Si;
      G = 0.5 * (G + G.transpose());

      // ½·tr(S⁻¹DS⁻¹D) = ½·<G, D>, both symmetric.
      f += 0.25 * wb * (G.array() * D.array()).sum();

      // ∂/∂θ_k of that term is ½·w_b·tr(G ∂Σ/∂θ_k); against a lower-vech
      // Jacobian column the off-diagonals carry twice.
      const double       scale = 0.5 * wb;
      const Eigen::Index off   = L.sigma_offsets[b];
      for (Eigen::Index cc = 0; cc < p; ++cc) {
        for (Eigen::Index rr = cc; rr < p; ++rr) {
          wv(off + vech_index(p, rr, cc)) =
              scale * ((rr == cc) ? G(rr, rr) : 2.0 * G(rr, cc));
        }
      }

      if (L.has_means && b < s.mean.size() && b < m.mu.size() &&
          s.mean[b].size() > 0 && m.mu[b].size() > 0) {
        const Eigen::VectorXd d = m.mu[b] - s.mean[b];
        const Eigen::VectorXd z = Si * d;
        f += 0.5 * wb * d.dot(z);
        uv.segment(L.mu_offsets[b], p) = wb * z;
      }
    }

    if (!std::isfinite(f)) {
      grad.setZero();
      return kInfinity;
    }
    if (eval->J_sigma.rows() != L.n_sigma_rows ||
        eval->J_sigma.cols() != x.size()) {
      grad.setZero();
      return kInfinity;
    }
    grad.noalias() = eval->J_sigma.transpose() * wv;
    if (L.has_means) {
      if (eval->J_mu.rows() != L.n_mu_rows ||
          eval->J_mu.cols() != x.size()) {
        grad.setZero();
        return kInfinity;
      }
      grad.noalias() += eval->J_mu.transpose() * uv;
    }
    if (!grad.allFinite()) {
      grad.setZero();
      return kInfinity;
    }
    return f;
  };
  return prob;
}

fit_expected<Weight>
expected_information_weight(const model::ModelEvaluator& ev,
                            const data::SampleStats& samp,
                            const Eigen::VectorXd& theta) {
  auto eval = ev.evaluate(theta, false, false);
  if (!eval.has_value()) {
    return std::unexpected(
        model_err(eval.error(), "gmm::expected_information_weight: theta"));
  }
  if (auto ok = validate_common_shapes(samp, eval->moments,
                                       "gmm::expected_information_weight");
      !ok.has_value()) {
    return std::unexpected(ok.error());
  }
  const Layout layout = make_layout(samp, eval->moments);

  Weight W;
  W.reserve(eval->moments.sigma.size());
  for (std::size_t b = 0; b < eval->moments.sigma.size(); ++b) {
    const Eigen::MatrixXd& Sigma_b = eval->moments.sigma[b];
    const Eigen::Index p = Sigma_b.rows();
    if (!Sigma_b.allFinite()) {
      return std::unexpected(make_err(FitError::Kind::NumericIssue,
          "gmm::expected_information_weight: block " + std::to_string(b) +
              " implied Sigma contains non-finite entries"));
    }
    // Same Kronecker structure as the GLS weight with A = Σ(θ) instead of S.
    // `fit_ml_irls` rebuilds this every outer iteration, so keeping it
    // structured turns an O(q³) refactor into a p×p Cholesky.
    auto bw = BlockWeight::normal_theory(
        Sigma_b, layout.has_means, FitError::Kind::NonPositiveDefiniteSigma,
        "gmm::expected_information_weight: block " + std::to_string(b));
    if (!bw.has_value()) return std::unexpected(bw.error());
    (void)p;
    W.push_back(std::move(*bw));
  }
  return W;
}

namespace {

// Stacked moment Jacobian of block b over [mean ; vech(cov)].
Eigen::MatrixXd block_moment_jacobian(const SampleStats& s,
                                      const model::Evaluation& e,
                                      const Layout& layout, std::size_t b) {
  const Eigen::Index p = e.moments.sigma[b].rows();
  const Eigen::Index pstar = vech_len(p);
  const Eigen::Index n_free = e.J_sigma.cols();
  Eigen::MatrixXd Jb = Eigen::MatrixXd::Zero(layout.block_rows[b], n_free);
  Eigen::Index off = 0;
  if (layout.has_means) {
    if (b < s.mean.size() && b < e.moments.mu.size() &&
        s.mean[b].size() > 0 && e.moments.mu[b].size() > 0 &&
        e.J_mu.rows() == layout.n_mu_rows) {
      Jb.topRows(p) = e.J_mu.block(layout.mu_offsets[b], 0, p, n_free);
    }
    off = p;
  }
  Jb.block(off, 0, pstar, n_free) =
      e.J_sigma.block(layout.sigma_offsets[b], 0, pstar, n_free);
  return Jb;
}

// Shared setup: evaluation with both Jacobians, layout, dense block weights.
struct QuadraticPoint {
  model::Evaluation eval;
  Layout layout;
  std::vector<Eigen::MatrixXd> W;
};

fit_expected<QuadraticPoint> quadratic_point(const model::ModelEvaluator& ev,
                                             const SampleStats& samp,
                                             const Eigen::VectorXd& theta,
                                             const Weight& weight,
                                             const char* who) {
  auto eval = ev.evaluate(theta, true, true);
  if (!eval.has_value()) return std::unexpected(model_err(eval.error(), who));
  if (auto ok = validate_common_shapes(samp, eval->moments, who); !ok.has_value()) {
    return std::unexpected(ok.error());
  }
  if (auto n = total_n_obs(samp); !n.has_value()) return std::unexpected(n.error());
  QuadraticPoint out;
  out.layout = make_layout(samp, eval->moments);
  if (eval->J_sigma.rows() != out.layout.n_sigma_rows ||
      eval->J_sigma.cols() != theta.size()) {
    return std::unexpected(make_err(FitError::Kind::NumericIssue,
        std::string(who) + ": covariance Jacobian shape does not match the moment layout"));
  }
  out.W.reserve(samp.S.size());
  for (std::size_t b = 0; b < samp.S.size(); ++b) {
    const Eigen::Index rows = out.layout.block_rows[b];
    if (weight.empty()) {
      out.W.push_back(Eigen::MatrixXd::Identity(rows, rows));
      continue;
    }
    if (weight.size() <= b || !weight[b].valid(rows)) {
      return std::unexpected(make_err(FitError::Kind::NumericIssue,
          std::string(who) + ": weight block " + std::to_string(b) +
              " missing or of the wrong dimension"));
    }
    out.W.push_back(weight[b].to_dense());
  }
  out.eval = std::move(*eval);
  return out;
}

// Convert h so that tr(G X) == hᵀ vech(X) for symmetric X.
Eigen::MatrixXd vech_gradient_to_trace_weight(const Eigen::VectorXd& h,
                                              Eigen::Index p) {
  Eigen::MatrixXd G = Eigen::MatrixXd::Zero(p, p);
  Eigen::Index k = 0;
  for (Eigen::Index c = 0; c < p; ++c) {
    for (Eigen::Index r = c; r < p; ++r, ++k) {
      if (r == c) {
        G(r, c) = h(k);
      } else {
        G(r, c) = G(c, r) = 0.5 * h(k);
      }
    }
  }
  return G;
}

}  // namespace

fit_expected<Eigen::MatrixXd>
moment_quadratic_hessian(const model::ModelEvaluator& ev,
                         const SampleStats& samp,
                         const Eigen::VectorXd& theta,
                         const Weight& weight) {
  const char* who = "gmm::moment_quadratic_hessian";
  auto pt = quadratic_point(ev, samp, theta, weight, who);
  if (!pt.has_value()) return std::unexpected(pt.error());
  auto assembled = ev.assembled(theta);
  if (!assembled.has_value()) return std::unexpected(model_err(assembled.error(), who));
  if (assembled->blocks.size() != samp.S.size()) {
    return std::unexpected(make_err(FitError::Kind::NumericIssue,
        std::string(who) + ": assembled block count does not match the sample"));
  }
  const auto locs = ev.param_locations();
  const Eigen::Index q = theta.size();
  if (locs.size() != static_cast<std::size_t>(q)) {
    return std::unexpected(make_err(FitError::Kind::NumericIssue,
        std::string(who) + ": parameter-location count mismatch"));
  }
  for (const auto& l : locs) {
    if (l.row < 0 || l.col < 0) {
      return std::unexpected(make_err(FitError::Kind::NumericIssue,
          std::string(who) + ": a free parameter is not a model-matrix cell"));
    }
  }
  const auto& layout = pt->layout;
  Eigen::MatrixXd H = Eigen::MatrixXd::Zero(q, q);
  for (std::size_t b = 0; b < samp.S.size(); ++b) {
    const double n_b = static_cast<double>(samp.n_obs[b]);
    const Eigen::MatrixXd Jb = block_moment_jacobian(samp, pt->eval, layout, b);
    const Eigen::MatrixXd& Wb = pt->W[b];
    const Eigen::VectorXd h = Wb * block_moment_delta(samp, pt->eval.moments, layout, b);
    H.noalias() += n_b * (Jb.transpose() * Wb * Jb);

    const Eigen::Index p = pt->eval.moments.sigma[b].rows();
    const Eigen::Index cov_off = layout.has_means ? p : 0;
    const auto& bm = assembled->blocks[b];
    const auto sow = detail::SecondOrderWeights::build(
        vech_gradient_to_trace_weight(h.segment(cov_off, vech_len(p)), p), bm,
        layout.has_means);
    std::vector<Eigen::Index> in_block;
    for (Eigen::Index k = 0; k < q; ++k) {
      if (locs[static_cast<std::size_t>(k)].block == static_cast<std::int8_t>(b)) {
        in_block.push_back(k);
      }
    }
    for (std::size_t ai = 0; ai < in_block.size(); ++ai) {
      const Eigen::Index a = in_block[ai];
      const auto& la = locs[static_cast<std::size_t>(a)];
      for (std::size_t ci = ai; ci < in_block.size(); ++ci) {
        const Eigen::Index c = in_block[ci];
        const auto& lc = locs[static_cast<std::size_t>(c)];
        double h2 = detail::second_sigma_trace(la, lc, sow, bm);
        if (layout.has_means) {
          h2 += h.head(p).dot(detail::second_mu(la, lc, bm, sow.A_alpha));
        }
        H(a, c) += n_b * h2;
        if (a != c) H(c, a) += n_b * h2;
      }
    }
  }
  H = (0.5 * (H + H.transpose())).eval();
  if (!H.allFinite()) {
    return std::unexpected(make_err(FitError::Kind::NonFiniteObjective,
        std::string(who) + ": non-finite Hessian"));
  }
  return H;
}

fit_expected<Eigen::MatrixXd>
moment_quadratic_nt_gradient_variance(const model::ModelEvaluator& ev,
                                      const SampleStats& samp,
                                      const Eigen::VectorXd& theta,
                                      const Weight& weight) {
  const char* who = "gmm::moment_quadratic_nt_gradient_variance";
  auto pt = quadratic_point(ev, samp, theta, weight, who);
  if (!pt.has_value()) return std::unexpected(pt.error());
  const auto& layout = pt->layout;
  const Eigen::Index q = theta.size();
  Eigen::MatrixXd Omega = Eigen::MatrixXd::Zero(q, q);
  for (std::size_t b = 0; b < samp.S.size(); ++b) {
    const Eigen::Index p = samp.S[b].rows();
    auto gamma = layout.has_means ? data::gamma_nt_with_means(samp.S[b])
                                  : data::gamma_nt(samp.S[b]);
    if (!gamma.has_value()) {
      return std::unexpected(make_err(FitError::Kind::NumericIssue,
          std::string(who) + ": normal-theory Gamma failed in block " +
              std::to_string(b) + ": " + gamma.error().detail));
    }
    if (gamma->rows() != layout.block_rows[b]) {
      return std::unexpected(make_err(FitError::Kind::NumericIssue,
          std::string(who) + ": normal-theory Gamma has the wrong dimension"));
    }
    (void)p;
    const Eigen::MatrixXd WJ =
        pt->W[b] * block_moment_jacobian(samp, pt->eval, layout, b);
    Omega.noalias() += static_cast<double>(samp.n_obs[b]) * (WJ.transpose() * (*gamma) * WJ);
  }
  Omega = (0.5 * (Omega + Omega.transpose())).eval();
  if (!Omega.allFinite()) {
    return std::unexpected(make_err(FitError::Kind::NonFiniteObjective,
        std::string(who) + ": non-finite gradient variance"));
  }
  return Omega;
}

fit_expected<MomentGradientFactor>
moment_quadratic_nt_gradient_factor(const model::ModelEvaluator& ev,
                                    const SampleStats& samp,
                                    const Eigen::VectorXd& theta,
                                    const Weight& weight) {
  const char* who = "gmm::moment_quadratic_nt_gradient_factor";
  auto pt = quadratic_point(ev, samp, theta, weight, who);
  if (!pt) return std::unexpected(pt.error());
  const auto& layout = pt->layout;
  Eigen::Index rows = 0;
  for (const auto& S : samp.S) rows += S.rows() * S.rows() + (layout.has_means ? S.rows() : 0);
  MomentGradientFactor out;
  out.factor.resize(rows, theta.size());
  out.score_residual = Eigen::VectorXd::Zero(rows);
  bool all_pd = true;
  Eigen::Index offset = 0;
  for (std::size_t b = 0; b < samp.S.size(); ++b) {
    const auto& S = samp.S[b];
    const Eigen::Index p = S.rows();
    if (!S.allFinite() || (S.diagonal().array() < 0).any())
      return std::unexpected(make_err(FitError::Kind::NumericIssue,
          std::string(who) + ": negative sample diagonal"));
    Eigen::VectorXd units = S.diagonal().cwiseSqrt();
    for (Eigen::Index i = 0; i < p; ++i) if (units[i] == 0) units[i] = 1;
    const Eigen::VectorXd inv = units.cwiseInverse();
    const Eigen::MatrixXd C = inv.asDiagonal() * S * inv.asDiagonal();
    Eigen::LLT<Eigen::MatrixXd> chol(C);
    Eigen::MatrixXd L;
    const bool pd = chol.info() == Eigen::Success;
    if (pd) {
      L = units.asDiagonal() * Eigen::MatrixXd(chol.matrixL());
    } else {
      // A semidefinite sample still has a gradient-variance factor. Clip only
      // roundoff-sized negative eigenvalues; the later QR must reject rank
      // loss rather than manufacture a standard-error scale.
      Eigen::SelfAdjointEigenSolver<Eigen::MatrixXd> eig(C);
      if (eig.info() != Eigen::Success || eig.eigenvalues().minCoeff() <
          -64 * std::numeric_limits<double>::epsilon() * static_cast<double>(p) * C.norm())
        return std::unexpected(make_err(FitError::Kind::NumericIssue,
            std::string(who) + ": sample covariance is indefinite"));
      L = units.asDiagonal() * eig.eigenvectors() *
          eig.eigenvalues().cwiseMax(0).cwiseSqrt().asDiagonal();
      all_pd = false;
    }
    const Eigen::Index mean_rows = layout.has_means ? p : 0;
    const Eigen::Index block_rows = mean_rows + p * p;
    Eigen::MatrixXd F = Eigen::MatrixXd::Zero(block_rows, layout.block_rows[b]);
    if (layout.has_means) F.topLeftCorner(p, p) = L.transpose();
    // Cov(S_ij,S_kl) = S_ik S_jl + S_il S_jk. Symmetric tensor columns
    // give this Gamma directly as F'F, including the vech diagonal factors.
    for (Eigen::Index j = 0; j < p; ++j) {
      for (Eigen::Index i = j; i < p; ++i) {
        const Eigen::MatrixXd tensor = (L.row(i).transpose() * L.row(j) +
            L.row(j).transpose() * L.row(i)) / std::sqrt(2.0);
        F.col(mean_rows + vech_index(p, i, j)).tail(p * p) =
            Eigen::Map<const Eigen::VectorXd>(tensor.data(), p * p);
      }
    }
    const double root_n = std::sqrt(static_cast<double>(samp.n_obs[b]));
    out.factor.middleRows(offset, block_rows).noalias() = root_n * F * pt->W[b] *
        block_moment_jacobian(samp, pt->eval, layout, b);
    if (pd) {
      const Eigen::MatrixXd L_inv = L.triangularView<Eigen::Lower>().solve(
          Eigen::MatrixXd::Identity(p, p));
      // The objective packs the lower triangle. Mirror those exact entries:
      // averaging upper/lower roundoff can change a nearly zero score.
      Eigen::MatrixXd R = pt->eval.moments.sigma[b] - S;
      R = R.selfadjointView<Eigen::Lower>();
      const Eigen::MatrixXd white = L_inv * R * L_inv.transpose() / std::sqrt(2.0);
      out.score_residual.segment(offset + mean_rows, p * p) = root_n *
          Eigen::Map<const Eigen::VectorXd>(white.data(), p * p);
      if (layout.has_means) {
        const auto delta = block_moment_delta(samp, pt->eval.moments, layout, b);
        out.score_residual.segment(offset, p) = root_n * L_inv * delta.head(p);
      }
    }
    offset += block_rows;
  }
  if (!all_pd) out.score_residual.resize(0);
  if (!out.factor.allFinite() || !out.score_residual.allFinite())
    return std::unexpected(make_err(FitError::Kind::NumericIssue,
        std::string(who) + ": non-finite factor or whitened score residual"));
  return out;
}

fit_expected<Weight>
fixed_moment_weight(const model::ModelEvaluator& ev, const data::SampleStats& samp,
                    const Eigen::VectorXd& theta0, FixedWeightKind kind,
                    const data::RawData* raw, FixedWeightOptions options) {
  constexpr const char* who = "fixed_moment_weight";
  if (kind == FixedWeightKind::Nt) return normal_theory_weight(ev, samp, theta0);
  if (kind == FixedWeightKind::Dls) {
    if (!raw) return std::unexpected(make_err(FitError::Kind::NumericIssue,
        "fixed_moment_weight: DLS requires complete raw observations"));
    return frontier::dls_weight(ev, samp, *raw, theta0, options);
  }
  auto moments = ev.sigma(theta0);
  if (!moments) return std::unexpected(model_err(moments.error(), who));
  if (auto shapes = validate_common_shapes(samp, *moments, who); !shapes)
    return std::unexpected(shapes.error());
  const auto layout = make_layout(samp, *moments);
  if (kind != FixedWeightKind::Uls && (!raw || !raw->mask.empty() || raw->X.size() != samp.S.size()))
    return std::unexpected(make_err(FitError::Kind::NumericIssue,
        "fixed_moment_weight: empirical weights require complete raw observations"));
  Weight out;
  for (std::size_t b = 0; b < samp.S.size(); ++b) {
    const auto p = samp.S[b].rows();
    const auto q = layout.block_rows[b];
    if (kind == FixedWeightKind::Uls) { out.push_back(BlockWeight::identity(q)); continue; }
    if (raw->X[b].cols() != p || b >= samp.n_obs.size() || raw->X[b].rows() != samp.n_obs[b])
      return std::unexpected(make_err(FitError::Kind::NumericIssue, "fixed_moment_weight: raw shape mismatch"));
    auto gamma = layout.has_means ? data::empirical_gamma_with_means(raw->X[b]) : data::empirical_gamma(raw->X[b]);
    if (!gamma) return std::unexpected(make_err(FitError::Kind::NumericIssue, gamma.error().detail));
    if (kind == FixedWeightKind::Dwls) {
      if (!gamma->diagonal().allFinite() || (gamma->diagonal().array() <= 0).any())
        return std::unexpected(make_err(FitError::Kind::NumericIssue, "fixed_moment_weight: non-positive Gamma diagonal"));
      out.push_back(BlockWeight::diagonal(gamma->diagonal().cwiseInverse()));
    } else if (kind == FixedWeightKind::Wls) {
      auto inverse = detail::symmetric_inverse_pd_gated(*gamma);
      if (!inverse.ok) return std::unexpected(make_err(FitError::Kind::NumericIssue,
          "fixed_moment_weight: observed Gamma is rank deficient"));
      auto weight = BlockWeight::dense(inverse.inverse, FitError::Kind::NumericIssue, who);
      if (!weight) return std::unexpected(weight.error());
      out.push_back(std::move(*weight));
    } else return std::unexpected(make_err(FitError::Kind::NumericIssue, "fixed_moment_weight: invalid kind"));
  }
  return out;
}

